def f(ax, ay):
    if ax == ay:
        raise ValueError("a_x must not equal a_y")
    return (ax * ay - 1) / (ax - ay)

def calculate_Ai(a, i):
    # a is the list [a_1, a_2, ..., a_{i+1}]
    N = i + 1
    Ai = 0

    for x in range(N):
        # Calculate P_x = Prod_{y!=x} f(a_{x+1}, a_{y+1})
        Px = 1.0
        for y in range(N):
            if x != y:
                try:
                    Px *= f(a[x], a[y])
                except ValueError as e:
                    return float('nan') # Should not happen
        Ai += Px

    return Ai

